def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    op = [h[1] for h in history]
    opp_def_count = op.count('D')
    if n >= 10 and opp_def_count * 2 >= n:
        return 'D'
    if n >= 2:
        last = history[-1]
        prev = history[-2]
        if last == ('C', 'D') and prev == ('D', 'C'):
            return 'C'
    if op[-1] == 'D':
        if n >= 2 and history[-2] == ('D', 'D'):
            return 'C'
        return 'D'
    return 'C'
